		reset()
	}
	switch cmd.Action {
	case "approve_plan":
		if next.PlanVersion == 0 {
			next.PlanVersion = 1
		}
		next.ApprovedPlanVersion = next.PlanVersion
		reset()
		p.Validation = ""
	case "submit_result":
		if next.ResultVersion == 0 {
			next.ResultVersion = 1
		}
		reset()
		p.Validation = ""
	case "request_changes", "replan":
		reset()
		if cmd.Action == "replan" {
